// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/detectors", wrapper.ListDetectors)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/detectors/{name}", wrapper.GetDetector)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/detectors/{name}/runs", wrapper.ListDetectorRuns)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/detectors/{name}/runs/{id}", wrapper.GetDetectorRun)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/clipboard/test", wrapper.RunClipboardTest)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/system/status", wrapper.GetSystemStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/network/status", wrapper.GetNetworkStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/firewall/status", wrapper.GetFirewallStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/firewall/open", wrapper.OpenFirewallSettings)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/recording/status", wrapper.GetRecordingStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/usb/status", wrapper.GetUsbStatus)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/usb/release", wrapper.ReleaseUsb)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/usb/eject", wrapper.EjectUsb)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/usb/files/locations", wrapper.ListUsbFileLocations)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/usb/files", wrapper.ListUsbFiles)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/usb/transfers", wrapper.ListUsbTransfers)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/usb/transfers", wrapper.StartUsbTransfer)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/usb/transfers/{id}/cancel", wrapper.CancelUsbTransfer)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/metrics", wrapper.GetMetrics)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/events", wrapper.ListEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/events", wrapper.CreateEvent)

	return m
}

