// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// RunClipboardTest 클립보드 카나리아 테스트 (macOS)
	// (POST /clipboard/test)
	RunClipboardTest(ctx context.Context, request RunClipboardTestRequestObject) (RunClipboardTestResponseObject, error)
	// ListDetectors 탐지기 동작 상태 조회
	// (GET /detectors)
	ListDetectors(ctx context.Context, request ListDetectorsRequestObject) (ListDetectorsResponseObject, error)
	// GetDetector 탐지기 상세 (현재 상태, 데이터 소스)
	// (GET /detectors/{name})
	GetDetector(ctx context.Context, request GetDetectorRequestObject) (GetDetectorResponseObject, error)
	// ListDetectorRuns 탐지기 실행 이력 (최신순)
	// (GET /detectors/{name}/runs)
	ListDetectorRuns(ctx context.Context, request ListDetectorRunsRequestObject) (ListDetectorRunsResponseObject, error)
	// GetDetectorRun 실행 1건의 상세 (당시 점검 항목 포함)
	// (GET /detectors/{name}/runs/{id})
	GetDetectorRun(ctx context.Context, request GetDetectorRunRequestObject) (GetDetectorRunResponseObject, error)
	// ListEvents 탐지 이벤트 목록 조회
	// (GET /events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// CreateEvent 탐지 이벤트 등록
	// (POST /events)
	CreateEvent(ctx context.Context, request CreateEventRequestObject) (CreateEventResponseObject, error)
	// OpenFirewallSettings 방화벽 설정 화면 열기 (macOS, 서버가 실행 중인 Mac 에서 열림)
	// (POST /firewall/open)
	OpenFirewallSettings(ctx context.Context, request OpenFirewallSettingsRequestObject) (OpenFirewallSettingsResponseObject, error)
	// GetFirewallStatus 방화벽 실행 여부와 설정 내역 (조회 시점에 수집)
	// (GET /firewall/status)
	GetFirewallStatus(ctx context.Context, request GetFirewallStatusRequestObject) (GetFirewallStatusResponseObject, error)
	// GetHealth 서버 상태 확인
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// GetMetrics 시계열 지표 (cpu.usage, mem.used_pct, net.rx_bps ...)
	// (GET /metrics)
	GetMetrics(ctx context.Context, request GetMetricsRequestObject) (GetMetricsResponseObject, error)
	// GetNetworkStatus 현재 네트워크 연결 상태와 외부 접속
	// (GET /network/status)
	GetNetworkStatus(ctx context.Context, request GetNetworkStatusRequestObject) (GetNetworkStatusResponseObject, error)
	// GetRecordingStatus 화면 녹화·마이크·카메라 사용 현황, 녹화/원격 도구, 녹화 권한
	// (GET /recording/status)
	GetRecordingStatus(ctx context.Context, request GetRecordingStatusRequestObject) (GetRecordingStatusResponseObject, error)
	// GetSystemStatus 현재 CPU/메모리/디스크/상위 프로세스
	// (GET /system/status)
	GetSystemStatus(ctx context.Context, request GetSystemStatusRequestObject) (GetSystemStatusResponseObject, error)
	// EjectUsb 외장 디스크 꺼내기 (force=true 이면 열린 파일을 무시하고 강제 언마운트)
	// (POST /usb/eject)
	EjectUsb(ctx context.Context, request EjectUsbRequestObject) (EjectUsbResponseObject, error)
	// ListUsbFiles 위치의 폴더 내용
	// (GET /usb/files)
	ListUsbFiles(ctx context.Context, request ListUsbFilesRequestObject) (ListUsbFilesResponseObject, error)
	// ListUsbFileLocations 파일 전송에 쓸 수 있는 위치 (PC 폴더, 마운트된 USB 디스크, 휴대폰 MTP 저장소)
	// (GET /usb/files/locations)
	ListUsbFileLocations(ctx context.Context, request ListUsbFileLocationsRequestObject) (ListUsbFileLocationsResponseObject, error)
	// ReleaseUsb USB 디스크/장치를 점유한 프로세스 종료 (선택 시 이어서 꺼내기)
	// (POST /usb/release)
	ReleaseUsb(ctx context.Context, request ReleaseUsbRequestObject) (ReleaseUsbResponseObject, error)
	// GetUsbStatus USB 장치·외장 디스크와 사용 중인 프로세스
	// (GET /usb/status)
	GetUsbStatus(ctx context.Context, request GetUsbStatusRequestObject) (GetUsbStatusResponseObject, error)
	// ListUsbTransfers 최근 파일 전송 작업 (최신순, 최대 20개)
	// (GET /usb/transfers)
	ListUsbTransfers(ctx context.Context, request ListUsbTransfersRequestObject) (ListUsbTransfersResponseObject, error)
	// StartUsbTransfer 파일 복사/이동 시작 (백그라운드 작업, 한 번에 하나)
	// (POST /usb/transfers)
	StartUsbTransfer(ctx context.Context, request StartUsbTransferRequestObject) (StartUsbTransferResponseObject, error)
	// CancelUsbTransfer 진행 중인 전송 취소 (전송 중이던 파일은 지워지고, 끝난 파일은 그대로)
	// (POST /usb/transfers/{id}/cancel)
	CancelUsbTransfer(ctx context.Context, request CancelUsbTransferRequestObject) (CancelUsbTransferResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

